#[inline]
pub unsafe fn OptimizeHuffmanForRle(
    mut length: c_int,
    mut counts: *mut size_t,
) {
    while length >= 0 {
        if length == 0 {
            return;
        }
        // SAFETY: `counts` points to an array with at least `length` elements per caller contract.
        if unsafe { *counts.add((length - 1) as usize) } != 0 {
            break;
        }
        length -= 1;
    }

    let good_for_rle = malloc(
        (length as c_uint as size_t)
            .wrapping_mul(::core::mem::size_of::<c_int>() as size_t),
    ) as *mut c_int;

    let mut i: c_int = 0;
    while i < length {
        // SAFETY: `good_for_rle` points to an allocation of at least `length` `c_int`s, and `i < length`.
        unsafe { *good_for_rle.add(i as usize) = 0 };
        i += 1;
    }

    // SAFETY: `length > 0` here due to the early return above, so `counts[0]` exists.
    let mut symbol: size_t = unsafe { *counts };
    let mut stride: c_int = 0;
    i = 0;

    while i < length + 1 {
        let at_end = i == length;
        // SAFETY: when `at_end` is false, `i < length`, so `counts[i]` is in-bounds.
        let cur = if at_end { symbol } else { unsafe { *counts.add(i as usize) } };
        if at_end || cur != symbol {
            if (symbol == 0 && stride >= 5) || (symbol != 0 && stride >= 7) {
                let start = i - stride;
                let mut k = start;
                while k < i {
                    // SAFETY: `k` ranges over `[i - stride, i)`, which is within `[0, length)`.
                    unsafe { *good_for_rle.add(k as usize) = 1 };
                    k += 1;
                }
            }
            stride = 1;
            if !at_end {
                symbol = cur;
            }
        } else {
            stride += 1;
        }
        i += 1;
    }

    stride = 0;
    // SAFETY: `length > 0` here, so `counts[0]` exists.
    let mut limit: size_t = unsafe { *counts };
    let mut sum: size_t = 0;
    i = 0;

    while i < length + 1 {
        let at_end = i == length;
        let trigger = if at_end {
            true
        } else {
            // SAFETY: `i < length` in this branch, so both accesses are in-bounds.
            unsafe { *good_for_rle.add(i as usize) != 0 || AbsDiff(*counts.add(i as usize), limit) >= 4 }
        };

        if trigger {
            if stride >= 4 || (stride >= 3 && sum == 0) {
                let mut count: c_int = sum
                    .wrapping_add((stride / 2) as size_t)
                    .wrapping_div(stride as size_t) as c_int;
                if count < 1 {
                    count = 1;
                }
                if sum == 0 {
                    count = 0;
                }
                let start = i - stride;
                let mut k = start;
                while k < i {
                    // SAFETY: `k` ranges over `[i - stride, i)`, which is within `[0, length)`.
                    unsafe { *counts.add(k as usize) = count as size_t };
                    k += 1;
                }
            }
            stride = 0;
            sum = 0;
            if i < length - 3 {
                // SAFETY: `i + 3 < length` in this branch, so the four reads are in-bounds.
                unsafe {
                    limit = (*counts.add(i as usize))
                        .wrapping_add(*counts.add((i + 1) as usize))
                        .wrapping_add(*counts.add((i + 2) as usize))
                        .wrapping_add(*counts.add((i + 3) as usize))
                        .wrapping_add(2)
                        .wrapping_div(4);
                }
            } else if i < length {
                // SAFETY: `i < length` in this branch, so the read is in-bounds.
                unsafe {
                    limit = *counts.add(i as usize);
                }
            } else {
                limit = 0;
            }
        }

        stride += 1;
        if !at_end {
            // SAFETY: `i < length` in this branch, so the read is in-bounds.
            unsafe {
                sum = sum.wrapping_add(*counts.add(i as usize));
            }
        }
        i += 1;
    }

    free(good_for_rle as *mut c_void);
}

